serde_json::json!({
    "api_base": { "description": "Regional base URL for the Cisco AI Defense Inspection API. Defaults to https://us.api.inspect.aidefense.security.cisco.com. Supported regions: us (us-west-2), ap (ap-ne-1), eu (eu-central-1). The environment variable `CISCO_AI_DEFENSE_API_BASE` is consulted as a fallback. The endpoint path is derived from inspection_type (/api/v1/inspect/chat for 'chat', /api/v1/inspect/mcp for 'mcp').", "required": false, "type": "string" },
    "api_key": { "description": "API key for the Cisco AI Defense inspection endpoint. If not provided, the `CISCO_AI_DEFENSE_API_KEY` environment variable is used. Sent in the `X-Cisco-AI-Defense-API-Key` header. Both the chat and MCP endpoints use this key.", "required": false, "type": "string" },
    "optional_params": { "description": "Optional parameters for the guardrail", "fields": { "enabled_rules": { "description": "Explicit list of Cisco AI Defense rules to evaluate. If omitted, the policies configured for the API key in the Cisco AI Defense UI are used.", "required": false, "type": "array" }, "fallback_on_error": { "default_value": "block", "description": "Behaviour when the Cisco AI Defense API is unavailable: 'allow' proceeds without scanning (high availability), 'block' rejects the request (maximum security).", "options": ["allow", "block"], "required": false, "type": "select" }, "inspect_path": { "description": "Override for the inspection endpoint path. Defaults to /api/v1/inspect/chat when inspection_type='chat' and /api/v1/inspect/mcp when inspection_type='mcp'.", "required": false, "type": "string" }, "inspection_type": { "default_value": "chat", "description": "Which Cisco AI Defense inspection surface to use. 'chat' scans LLM model conversations via /api/v1/inspect/chat. 'mcp' scans MCP tool calls via /api/v1/inspect/mcp. Each guardrail instance targets exactly one surface; configure two guardrails to scan both chat and MCP traffic.", "options": ["chat", "mcp"], "required": false, "type": "select" }, "integration_profile_id": { "description": "Integration profile id to apply (advanced).", "required": false, "type": "string" }, "integration_profile_version": { "description": "Integration profile version to apply (advanced).", "required": false, "type": "string" }, "integration_tenant_id": { "description": "Integration tenant id to apply (advanced).", "required": false, "type": "string" }, "integration_type": { "description": "Integration type to apply (advanced).", "required": false, "type": "string" }, "on_flagged_action": { "default_value": "block", "description": "Action to take when Cisco AI Defense flags content. 'block' raises an HTTPException; 'monitor' logs the detection and lets the request continue.", "required": false, "type": "string" }, "timeout": { "default_value": 10.0_f64, "description": "Timeout (seconds) for Cisco AI Defense API calls (1-60).", "required": false, "type": "number" } }, "required": false, "type": "nested" },
    "ui_friendly_name": "Cisco AI Defense",
})
